"use client";
import type { PremiumPrice } from "@/components/premium-upgrade-dialog";
import { useRoleSuggestions } from "@/components/role-allowance";
import {
  startTransition,
  useEffect,
  useRef,
  useState,
  useTransition,
} from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { saveContact, checkContactEmail } from "@/lib/actions";
import { normalizedEmail } from "@/lib/validation";
import { suggestNameFromEmail } from "@/lib/contacts/suggestNameFromEmail";
import type { ActionResult } from "@/lib/errors";
import { useSuccessNotification } from "@/components/notifications";
import { Feedback, useUnsavedChanges } from "@/components/forms";
import { RoleChips } from "./RoleChips";
import styles from "./contacts.module.css";

export function NewContactForm({
  contact,
  roles = [],
}: {
  premiumPrice?: PremiumPrice;
  roles?: string[];
  contact?: {
    id: string;
    name: string;
    email: string;
    company: string | null;
    jobRole: string | null;
  };
}) {
  const [manualName, setManualName] = useState(!!contact?.name);
  const [email, setEmail] = useState(contact?.email ?? "");
  const [previouslyEmailed, setPreviouslyEmailed] = useState(false);
  const emailVersion = useRef(0);
  useEffect(() => {
    const parsed = normalizedEmail.safeParse(email);
    if (!parsed.success) return;
    let active = true;
    const version = emailVersion.current;
    const timer = setTimeout(() => {
      startTransition(async () => {
        try {
          const matched = await checkContactEmail(parsed.data);
          if (active && version === emailVersion.current)
            setPreviouslyEmailed(matched);
        } catch {
          // The advisory lookup must never prevent saving a contact.
        }
      });
    }, 300);
    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [email]);
  const [name, setName] = useState(contact?.name ?? "");
  const [jobRole, setJobRole] = useState(contact?.jobRole ?? "");
  const { list, suggestions } = useRoleSuggestions(roles);
  const [saved, setSaved] = useState(false);
  const [result, setResult] = useState<ActionResult>();
  useEffect(() => {
    if (!saved) return;
    const timer = setTimeout(() => setSaved(false), 1800);
    return () => clearTimeout(timer);
  }, [saved]);
  const [pending, start] = useTransition();
  const [dirty, setDirty] = useState(false);
  useUnsavedChanges(dirty);
  const router = useRouter();
  const notifySuccess = useSuccessNotification();
  const formRef = useRef<HTMLFormElement>(null);
  const focusSubmissionErrors = useRef(false);
  useEffect(() => {
    if (!pending && result?.ok === false && focusSubmissionErrors.current) {
      focusSubmissionErrors.current = false;
      formRef.current
        ?.querySelector<HTMLElement>("[aria-invalid='true']")
        ?.focus();
    }
  }, [result, pending]);
  function clearFieldError(field: string) {
    setResult((current) => {
      if (!current) return current;
      const fieldErrors = { ...current.fieldErrors };
      delete fieldErrors[field];
      return { ok: false, message: "", fieldErrors };
    });
  }
  return (
    <aside
      id="new-contact"
      aria-labelledby="new-contact-heading"
      className={`workspace-mono:p-5.5 workspace-mono:rounded-[12px] workspace-mono:shadow-none workspace-mono:transform-none workspace-mono:backdrop-blur-none workspace-mono:static! workspace-mono:[@media(max-width:479px)]:p-5 hover-card min-w-0 rounded-[var(--appearance-radius,24px)] border border-[var(--contacts-border)] bg-[var(--contacts-surface)] p-[26px] backdrop-blur-sm min-[900px]:sticky min-[900px]:top-5`}
    >
      <form
        ref={formRef}
        noValidate
        className={`${styles.contactForm} contact-form space-y-[18px] workspace-mono:grid workspace-mono:grid-cols-2 workspace-mono:gap-y-4 workspace-mono:gap-x-3`}
        onReset={() => {
          emailVersion.current++;
          setPreviouslyEmailed(false);
          setEmail(contact?.email ?? "");
        }}
        onChange={() => {
          setDirty(true);
          setSaved(false);
          setResult((current) => (current?.ok ? undefined : current));
        }}
        onSubmit={(event) => {
          event.preventDefault();
          const form = new FormData(event.currentTarget);
          setResult(undefined);
          setSaved(false);
          start(async () => {
            const r = await saveContact(form);
            focusSubmissionErrors.current = !r.ok;
            setResult(r);
            if (r.ok) {
              emailVersion.current++;
              setPreviouslyEmailed(false);
              notifySuccess("Contact saved successfully.");
              setSaved(true);
              setDirty(false);
              if (!contact) {
                formRef.current?.reset();
                setName("");
                setJobRole("");
                setManualName(false);
              }
              router.refresh();
            }
          });
        }}
      >
        <h2
          id="new-contact-heading"
          className="text-[22px] font-extrabold tracking-[-.03em] workspace-mono:text-[20px] workspace-mono:mb-1!"
        >
          {contact ? "Edit contact" : "New contact"}
        </h2>
        {suggestions}
        {contact && <input type="hidden" name="id" value={contact.id} />}
        {(
          [
            {
              name: "email",
              label: "Email",
              placeholder: "[REDACTED_EMAIL]",
              max: 254,
            },
            {
              name: "name",
              label: "Name",
              placeholder: "Alex Morgan",
              max: 120,
            },
            {
              name: "company",
              label: "Company",
              placeholder: "Acme",
              max: 160,
            },
            {
              name: "jobRole",
              label: "Job role",
              placeholder: "e.g. Platform Engineer",
              max: 160,
            },
          ] as const
        ).map((f) => (
          <div key={f.name} data-contact-field={f.name}>
            <label
              htmlFor={`contact-${f.name}`}
              className="mb-[7px] block text-sm font-semibold workspace-mono:text-[12px]"
            >
              {f.label}
              {f.name === "company" && (
                <span className="ml-2 font-normal text-[var(--contacts-muted)]">
                  Optional
                </span>
              )}
            </label>
            <input
              data-slot="input"
              className={`w-full workspace-mono:h-10.5 workspace-mono:px-3 workspace-mono:text-[13px] h-11.5 rounded-[var(--appearance-radius,_14px)] [border:1px_solid_var(--contacts-border)] [background:var(--contacts-inset)] py-0 px-4 text-[var(--contacts-text)] [&[aria-invalid='true']]:border-[var(--contacts-red)]`}
              id={`contact-${f.name}`}
              list={f.name === "jobRole" ? list : undefined}
              data-previously-emailed={
                previouslyEmailed && f.name === "email" ? "true" : undefined
              }
              disabled={pending}
              aria-invalid={!!result?.fieldErrors?.[f.name]}
              aria-describedby={
                [
                  result?.fieldErrors?.[f.name] ? `error-${f.name}` : "",
                  f.name === "name" && !manualName && !!name
                    ? "contact-name-suggestion"
                    : "",
                  previouslyEmailed && f.name === "email"
                    ? "contact-email-history-note"
                    : "",
                ]
                  .filter(Boolean)
                  .join(" ") || undefined
              }
              name={f.name}
              type={f.name === "email" ? "email" : "text"}
              defaultValue={
                f.name === "company" ? (contact?.[f.name] ?? "") : undefined
              }
              value={
                f.name === "email"
                  ? email
                  : f.name === "name"
                    ? name
                    : f.name === "jobRole"
                      ? jobRole
                      : undefined
              }
              onChange={(e) => {
                clearFieldError(f.name);
                if (f.name === "email") {
                  emailVersion.current++;
                  setPreviouslyEmailed(false);
                  setEmail(e.target.value);
                }
                if (f.name === "name") {
                  setManualName(true);
                  setName(e.target.value);
                }
                if (f.name === "email" && !manualName) {
                  setName(suggestNameFromEmail(e.target.value));
                  clearFieldError("name");
                }
                if (f.name === "jobRole") setJobRole(e.target.value);
              }}
              required={f.name !== "company"}
              maxLength={f.max}
              autoComplete="off"
              spellCheck={f.name !== "email"}
              placeholder={f.placeholder}
            />
            {f.name === "name" && !manualName && !!name && (
              <p
                id="contact-name-suggestion"
                className="mt-1.5 text-[12.5px] text-[var(--contacts-muted)]"
              >
                Suggested from the email. Check it before saving.
              </p>
            )}
            {f.name === "jobRole" && (
              <>
                <RoleChips
                  variant="contact-form"
                  roles={roles}
                  value={jobRole}
                  disabled={pending}
                  onChoose={(role) => {
                    setJobRole(role);
                    setDirty(true);
                    setSaved(false);
                    clearFieldError("jobRole");
                  }}
                />
              </>
            )}
            {result?.fieldErrors?.[f.name] && (
              <p
                id={`error-${f.name}`}
                className="mt-1.5 text-[12.5px] text-[var(--contacts-red)]"
              >
                {result.fieldErrors[f.name].replace(/\bPaid\b/g, "Premium")}
              </p>
            )}
          </div>
        ))}
        <p
          id="contact-email-history-note"
          role="status"
          className="text-[12.5px] text-warning"
          hidden={!previouslyEmailed}
        >
          {previouslyEmailed
            ? "You’ve already emailed this address. You can still save this contact and send a follow-up."
            : ""}
        </p>
        <p className="text-[12.5px] text-[var(--contacts-muted)] workspace-mono:text-[11.5px] workspace-mono:leading-[1.65]">
          Names from email addresses are suggestions. Correct them before
          saving. Enter actual names, companies, and roles here.
        </p>
        {result?.ok === false && (
          <Feedback result={result} planLabel="Premium" inlineFieldErrors />
        )}
        <div className="flex gap-2">
          <button
            className={`${styles.primary} workspace-mono:min-h-10.5 workspace-mono:py-2.5 workspace-mono:text-[13px] button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none inline-flex items-center justify-center gap-2 min-h-11.5 py-3 px-6 rounded-full [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] text-[14px] font-bold shadow-none w-full`}
            type="submit"
            disabled={pending}
          >
            {pending ? "Saving…" : "Save contact"}
          </button>
          {contact && (
            <Link
              href="/contacts"
              className={`${styles.secondary} secondary-button button-interaction inline-flex items-center justify-center min-h-11 py-2 px-4 [border:1px_solid_var(--contacts-strong)] rounded-full text-[13px] font-semibold text-[var(--contacts-purple)]`}
            >
              Cancel
            </Link>
          )}
        </div>
        <p
          role="status"
          className="workspace-mono:empty:hidden text-center text-[13px] font-semibold text-[var(--contacts-green)]"
        >
          {saved ? "Contact saved ✓" : ""}
        </p>
      </form>
    </aside>
  );
}
